 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    # The canvas/background is the most frequent color.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [[bg for _ in range(w)] for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            y0 = min(y for y, _ in cells)
            y1 = max(y for y, _ in cells)
            x0 = min(x for _, x in cells)
            x1 = max(x for _, x in cells)
            area = (y1 - y0 + 1) * (x1 - x0 + 1)
            # Dense, sizeable components are the solid panels; their bounding
            # boxes restore marker/noise pixels that interrupt the panel.
            if len(cells) >= 5 and area >= 6 and len(cells) / area >= 0.60:
                for y in range(y0, y1 + 1):
                    for x in range(x0, x1 + 1):
                        out[y][x] = color
    return out


def _self_check():
    sample = [
        [8,8,8,8,8,8,8,8,8,8,6,6,6,6,4],
        [7,7,7,8,8,8,8,8,8,8,6,6,6,6,6],
        [7,2,7,8,8,8,8,8,8,8,8,8,8,8,8],
    ]
    result = transform(sample)
    assert result[0][0:3] == [7,7,7]
    assert result[2][1] == 7
    assert result[0][14] == 8


if __name__ == '__main__':
    _self_check()
